/* Custom JavaScript functionality for [[Template:Countdown]] and [[Template:Seasons]]. */
(function () {
	/** @type {CountdownData[]} */
	const activeCountdowns = [];

	const MINUTE_SECONDS = 60;
	const HOUR_SECONDS = 3600;
	const DAY_SECONDS = 86400;
	const WEEK_SECONDS = 604800;

	const SEASON_DURATION = 576 * MINUTE_SECONDS;
	const ALL_SEASON_DURATION = 4 * SEASON_DURATION;

	/** @type {Season[]} */
	const SEASON_MAP = ["Spring", "Summer", "Autumn", "Winter"];
	/** @type {Record<Season, number>} *///@ts-ignore
	const SEASON_NUMS = SEASON_MAP.reduce((acc, season, index) => {
		acc[season] = index;
		return acc;
	}, {});

	const urlParams = new URLSearchParams(window.location.search);
	/** @type {typeof console.log} */
	const log =
		urlParams.get("debugCountdowns") === "1"
			? console.log.bind(console)
			: () => {};

	/**
	 * Formats the time for use in countdowns.
	 * @param {number} diffSeconds
	 * @param {CountdownData} [opts]
	 * @return {string}
	 */
	function formatTime(diffSeconds, opts) {
		const days = Math.floor(diffSeconds / DAY_SECONDS);
		diffSeconds %= DAY_SECONDS;
		const hours = Math.floor(diffSeconds / HOUR_SECONDS);
		diffSeconds %= HOUR_SECONDS;
		const mins = Math.floor(diffSeconds / MINUTE_SECONDS);
		diffSeconds %= MINUTE_SECONDS;
		const secs = Math.ceil(diffSeconds);

		const output = [];
		if (days > 0) output.push(`${days}d`);
		if (hours > 0 || days > 0) output.push(`${hours}h`);
		if (mins > 0 || hours > 0 || days > 0) output.push(`${mins}m`);
		if (secs > 0 || (opts && opts.always_show_seconds)) output.push(`${secs}s`);

		return output.join(" ");
	}

	const TIME_UNIT_MAP = {
		'': 1,
		s: 1,
		m: MINUTE_SECONDS,
		h: HOUR_SECONDS,
		d: DAY_SECONDS,
	}

	/**
	 * Converts a human-readable duration format to a number of seconds.
	 * @param {string} timeString
	 * @return {number}
 	*/
	function parseTime(timeString) {
		if (!timeString) return 0
		let total = 0
		for (const entry of timeString.split(' ')) {
			const [, numStr, unit] = entry.match(/^(\-?[\d\.]+)(\w?)$/) ?? []
			const num = Number(numStr)
			if (!numStr || !num) continue
			if (!TIME_UNIT_MAP[unit]) {
				throw new Error(`Invalid time unit "${unit}"`)
			}
			total += num * TIME_UNIT_MAP[unit]
		}
		return total
	}

	/**
	 * Gets the name of the current season.
	 * @param {Date?} timeNow
	 * @returns {Season}
	 */
	function getCurrentSeason(timeNow) {
		return SEASON_MAP[
			Math.floor(
				((timeNow?.getTime() ?? Date.now()) / (SEASON_DURATION * 1000)) % 4
			)
		];
	}

	/**
	 * Gets the time of the next occurrence of the specified season.
	 * @param {Season} season
	 * @param {Date?} timeNow
	 * @returns {number}
	 */
	function getNextSeasonTime(season, timeNow) {
		let seasonNum = SEASON_NUMS[season];
		let nextYearTime =
			Math.floor(
				(timeNow?.getTime() ?? Date.now()) / (ALL_SEASON_DURATION * 1000) +
				(1 - seasonNum / 4)
			) * ALL_SEASON_DURATION;
		return nextYearTime + SEASON_DURATION * seasonNum;
	}

	/**
	 * Gets the tooltip for a specific timestamp that displays it in the user's local time.
	 * @param {number} time
	 * @return {string}
	 */
	function getCountdownTooltip(time) {
		return new Date(time)
			.toLocaleString(undefined, {
				dateStyle: "medium",
				timeStyle: "short"
			})
	}

	/**
	 * Returns the season that comes after the given one.
	 * @param {Season} season
	 */
	function nextSeason(season) {
		return SEASON_MAP[(SEASON_NUMS[season] + 1) % SEASON_MAP.length];
	}

	/**
	 * Seasons
	 * @param {Season} season
	 * @param {HTMLTableRowElement} row
	 * @param {HTMLTableCellElement} container
	 * @param {Date?} timeNow
	 */
	function updateSeasonCountdown(season, row, container, timeNow) {
		const isCurrent = getCurrentSeason(timeNow) === season;
		row.classList.toggle("current-season", isCurrent);

		const targetTime = getNextSeasonTime(
			isCurrent ? nextSeason(season) : season,
			timeNow
		);
		const formatted = formatTime(
			Math.floor(targetTime - (timeNow?.getTime() ?? Date.now()) / 1000)
		);

		container.innerHTML = `${isCurrent ? "Ends in" : "Starts in"
			} <span class="season-cd-content" title="${getCountdownTooltip(targetTime * 1000)}">${formatted}</span>`;
	}

	function updateCountdowns() {
		const timeNow = new Date();
		for (let countdown of activeCountdowns) {
			switch (countdown.type) {
				case "normal":
					const diffSeconds = Math.floor(
						(countdown.time - timeNow.getTime()) / 1000
					);
					countdown.element.textContent =
						diffSeconds > 0 || countdown.allow_count_up
							? formatTime(Math.abs(diffSeconds), countdown)
							: countdown.ended_text ?? "";

					countdown.element.title = getCountdownTooltip(countdown.time)
					break;
				case "recurring": {
					const START = countdown.time;
					const END = START + countdown.duration;

					const PERIOD_DURATION = countdown.period
					const PERIOD_OFFSET = countdown.period_offset ?? 0

					const periodStart = new Date(timeNow.getTime() - ((timeNow.getTime() - (PERIOD_OFFSET * 1000)) % (PERIOD_DURATION * 1000)));
					const timeInPeriod = (timeNow.getTime() - periodStart.getTime()) / 1000

					const IN_PROGRESS =
						(timeInPeriod >= START && timeInPeriod < END) ||
						(END > PERIOD_DURATION && timeInPeriod <= (END % PERIOD_DURATION));

					const targetTime = (IN_PROGRESS ? END : START) % (PERIOD_DURATION + 1);

					const diffSeconds =
						targetTime >= timeInPeriod
							? targetTime - timeInPeriod
							: PERIOD_DURATION - timeInPeriod + targetTime;

					const prefixElement = countdown.element.parentElement.querySelector('.countdown-prefix')

					const prefix = IN_PROGRESS ? 'Ends in' : 'Starts in'
					const formattedCountdown = formatTime(diffSeconds, countdown)

					if (prefixElement) {
						prefixElement.textContent = prefix + ':'
						countdown.element.textContent = formattedCountdown
					} else {
						countdown.element.textContent = `${prefix} ${formatTime}`
					}

					countdown.element.title = getCountdownTooltip(periodStart.getTime() + (targetTime * 1000) + (timeInPeriod > targetTime ? (PERIOD_DURATION * 1000) : 0))
					break;
				}
				case "seasons":
					for (const season of SEASON_MAP)
						updateSeasonCountdown(
							season,
							countdown[`${season.toLowerCase()}_row`],
							countdown[`${season.toLowerCase()}_cd`],
							timeNow
						);
					break;
			}
		}
	}

	/**
	 * @param {HTMLElement} container
	 */
	function addCountdown(container) {
		if (
			activeCountdowns.find(function (cd) {
				return cd.element == container;
			})
		) {
			log("Found duplicate, ignoring");
			return;
		}

		log("Adding", container.outerHTML);

		/** @type {CountdownData} */
		let data;
		if (container.classList.contains("countdown-seasons")) {
			data = {
				type: "seasons",
				element: container,
				...Object.fromEntries(
					SEASON_MAP.map((season) => [
						[
							`${season.toLowerCase()}_row`,
							container.querySelector(`.season-${season.toLowerCase()}`)
						],
						[
							`${season.toLowerCase()}_cd`,
							container.querySelector(`.season-${season.toLowerCase()} .season-cd`)
						]
					]).flat()
				)
			};
		} else {
			data = {
				type: container.getAttribute("data-type") || "normal",
				element: container,
				time:
					container.getAttribute("data-timestamp") != undefined ?
						parseTime(container.getAttribute("data-timestamp")) :
						Date.parse(container.getAttribute("data-time")),
				duration: parseTime(container.getAttribute("data-duration")),
				period: parseTime(container.getAttribute("data-period")),
				period_offset: parseTime(container.getAttribute("data-period-offset")),
				allow_count_up: container.getAttribute("data-allow-count-up") === "true",
				always_show_seconds: container.getAttribute("data-show-seconds") === "true",
				ended_text: container.getAttribute("data-ended-text")
			};
		}

		log("Added as", JSON.stringify(data, null, "\t"));

		activeCountdowns.push(data);
	}

	function init() {
		// This hook ensures that we init again on live preview
		mw.hook("wikipage.content").add(function (
			/** @type {HTMLElement[]} */ contents
		) {
			document.querySelectorAll(".countdown").forEach(addCountdown);

			document.querySelectorAll(".countdown-container").forEach(function (/** @type {HTMLDivElement} */ container) {
			    if (container.hasAttribute("data-bg-image")) {
			        const bgUrl = `url("https://fischipedia.org/wiki/Special:Redirect/file/${encodeURIComponent(
			            container.getAttribute("data-bg-image")
			        )}")`;

			        // Pass the dynamic URL to a CSS variable
			        container.style.setProperty("--dynamic-bg-image", bgUrl);
			    }
			});

			updateCountdowns();
		});

		setInterval(function () {
			updateCountdowns();
		}, 1000);
	}

	function onLoad() {
		//@ts-ignore
		if ("dev" in window && window.dev.countdownsLoaded) {
			console.debug("Countdowns script already loaded, aborting...");
			return;
		}

		//@ts-ignore
		window.dev = window.dev ?? {}; //@ts-ignore
		window.dev.countdownsLoaded = true; //@ts-ignore
		window.addCountdown = addCountdown;

		init();
	}

	// The document cannot change readyState between the if and else
	if (document.readyState == "loading") {
		document.addEventListener("readystatechange", onLoad);
	} else {
		onLoad();
	}

	///////////////////////////////////////////////////////////////////////////////////////////////////////
})();
